    private const ulong Salt=0x504552414C4B4852UL;private readonly int ox,oy,oz;private readonly double cx,cz,rx,rz,roof,floor,ex,ez,erx,erz,rise,diffDepth,seed;private readonly Peg[] pegs;private readonly Frac[] fracs;
